1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.util.Collection;
13	import java.util.List;
14	
15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName",
22	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
23	    @Mapping(target = "initials",
24	        expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" "
25	            + "+ Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
26	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
27	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
28	    @Mapping(target = "locality", expression = "java(locality(owner))")
29	    @Mapping(target = "bulkSignupWarning", expression = "java(bulkSignupWarning(owner))")
30	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
31	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
32	    @Mapping(target = "identityKey",
33	        expression = "java(org.springframework.samples.petclinic.rest.function.owner.OwnerIdentity.of(owner))")
34	    OwnerDto toOwnerDto(Owner owner);
35	
36	    /**
37	     * Derives the owner's preferred contact channel at read time: {@code EMAIL} when an email is
38	     * present, otherwise {@code PHONE}.
39	     */
40	    default OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
41	        return hasEmail(owner) ? OwnerDto.ContactPreferenceEnum.EMAIL
42	            : OwnerDto.ContactPreferenceEnum.PHONE;
43	    }
44	
45	    /**
46	     * Derives the owner's age band at read time from {@code birthDate}, computed against
47	     * {@code registrationDate} (falling back to the current date when none is stored):
48	     * {@code MINOR} when under 18, {@code ADULT} when 18-64, {@code SENIOR} when 65 or older.
49	     * Returns {@code null} when no birth date was supplied, so the field is absent for owners
50	     * created without one.
51	     */
52	    default OwnerDto.AgeBandEnum ageBand(Owner owner) {
53	        java.time.LocalDate birthDate = owner.getBirthDate();
54	        if (birthDate == null) {
55	            return null;
56	        }
57	        java.time.LocalDate asOf = owner.getRegistrationDate() != null
58	            ? owner.getRegistrationDate() : java.time.LocalDate.now();
59	        int age = java.time.Period.between(birthDate, asOf).getYears();
60	        if (age < 18) {
61	            return OwnerDto.AgeBandEnum.MINOR;
62	        }
63	        if (age < 65) {
64	            return OwnerDto.AgeBandEnum.ADULT;
65	        }
66	        return OwnerDto.AgeBandEnum.SENIOR;
67	    }
68	
69	    /** Whether the owner has a non-blank email address. */
70	    default boolean hasEmail(Owner owner) {
71	        return owner.getEmail() != null && !owner.getEmail().isBlank();
72	    }
73	
74	    /**
75	     * Reports the owner's bulk-signup warning: {@code true} when more than 80 owners had already
76	     * been created on this owner's registration business day at the time it was created. Treats a
77	     * missing value (owners created before this rule existed) as {@code false}.
78	     */
79	    default boolean bulkSignupWarning(Owner owner) {
80	        return Boolean.TRUE.equals(owner.getBulkSignupWarning());
81	    }
82	
83	    /**
84	     * Computes the owner's check digit: a single Luhn check digit (0-9) over the digits contained
85	     * in {@code customerCode}, derived at read time. Returns {@code null} when no customer code has
86	     * been assigned.
87	     */
88	    default Integer checkDigit(Owner owner) {
89	        String customerCode = owner.getCustomerCode();
90	        if (customerCode == null) {
91	            return null;
92	        }
93	        int sum = 0;
94	        boolean dbl = true;
95	        for (int i = customerCode.length() - 1; i >= 0; i--) {
96	            char c = customerCode.charAt(i);
97	            if (c < '0' || c > '9') {
98	                continue;
99	            }
100	            int d = c - '0';
101	            if (dbl) {
102	                d *= 2;
103	                if (d > 9) {
104	                    d -= 9;
105	                }
106	            }
107	            sum += d;
108	            dbl = !dbl;
109	        }
110	        return (10 - (sum % 10)) % 10;
