11	 * have already been registered on the request's effective business day (by {@code registrationDate}),
12	 * with a 429 via {@link DailyOwnerLimitException}.
13	 *
14	 * <p>The effective business day is the supplied registration date, or the server date when omitted,
15	 * rolled forward over a weekend to Monday — exactly the adjusted date {@link BuildOwner} stores on a
16	 * new owner. Counts existing owners whose stored {@code registrationDate} equals that business day,
17	 * so the count reflects owners registered on the same business day. Runs before {@link BuildOwner}.
18	 */
19	public class CheckDailyOwnerLimit {
20	
21	    /** Maximum number of owners permitted to register in a single day. */
22	    private static final int DAILY_LIMIT = 100;
23	
24	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
25	            throws DailyOwnerLimitException {
26	        // The limit is per business day of the EFFECTIVE registration date: use the supplied date
27	        // when present, else the server date, then roll a weekend forward to Monday — matching the
28	        // adjusted date stored on new owners (see BuildOwner), so the count lines up.
29	        LocalDate supplied = request.getRegistrationDate();
30	        LocalDate businessDay = BusinessDay.rollForward(supplied != null ? supplied : LocalDate.now());
31	        long count = BusinessDay.countOwnersOn(businessDay, ownerRepository);
32	        if (count >= DAILY_LIMIT) {
33	            throw new DailyOwnerLimitException(count);
34	        }
35	    }
36	}
