11	/**
12	 * Household assignment for {@code POST /owners}. When the request opts in via
13	 * {@code sharesHousehold} true, the new owner joins the household of any existing owner it
14	 * {@link OwnerHousehold#matches matches}. Both the joining owner and the matched existing
15	 * owners are assigned the same {@code householdId} — a stable shared identifier (see
16	 * {@link OwnerHousehold#deriveId}) — so the household is discoverable from any of its members.
17	 * If a matched owner already carries a {@code householdId}, that value is reused so the
18	 * identifier stays stable as further members join.
19	 *
20	 * <p>Runs within the create transaction (after {@link BuildOwner}/{@link AssignCustomerCode},
21	 * before {@link SaveOwner}) so the back-filled identifiers on existing owners commit with the
22	 * new owner. Requests without {@code sharesHousehold} leave {@code householdId} null.
23	 */
24	public class AssignHousehold {
25	
26	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
27	        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
28	            return;
29	        }
30	        List<Owner> matches = new ArrayList<>();
31	        String householdId = null;
32	        for (Owner existing : ownerRepository.findAll()) {
33	            if (OwnerHousehold.matches(request, existing)) {
34	                matches.add(existing);
35	                if (householdId == null && existing.getHouseholdId() != null) {
36	                    householdId = existing.getHouseholdId();
37	                }
38	            }
39	        }
40	        if (householdId == null) {
41	            householdId = OwnerHousehold.deriveId(request);
42	        }
43	        owner.setHouseholdId(householdId);
44	        for (Owner existing : matches) {
45	            if (!householdId.equals(existing.getHouseholdId())) {
46	                existing.setHouseholdId(householdId);
47	                ownerRepository.save(existing);
48	            }
49	        }
50	    }
